import re
# Ordered: first match wins. Patterns are on upper-cased text with word boundaries.
CATS = [
 ("Gold price report (lagging)", r"\b(SPOT GOLD|GOLD (RISES|FALLS|DROPS|JUMPS|SLIPS|TUMBLES|SURGES|EXTENDS|PARES|TURNS|HITS|CLIMBS|SINKS|RECORD|PRICES?)|GOLD FUTURES|BULLION (RISES|FALLS|DROPS)|SILVER (RISES|FALLS|DROPS|JUMPS|SURGES|TUMBLES))\b"),
 ("US CPI/PPI inflation", r"\b(CPI|CONSUMER PRICES|PPI|PRODUCER PRICES|CORE PCE|PCE PRICE|PCE)\b"),
 ("US jobs (NFP/claims/JOLTS/ADP)", r"\b(NONFARM|NON-FARM|PAYROLLS?|UNEMPLOYMENT RATE|JOBLESS CLAIMS|CONTINUING CLAIMS|JOLTS|JOB OPENINGS|ADP|AVERAGE HOURLY EARNINGS)\b"),
 ("US growth data (GDP/ISM/retail/PMI)", r"\b(GDP|ISM|PMI|RETAIL SALES|DURABLE GOODS|INDUSTRIAL PRODUCTION|HOUSING STARTS|UMICH|MICHIGAN SENTIMENT|CONSUMER CONFIDENCE|CONSUMER SENTIMENT|EMPIRE STATE|PHILLY FED|PHILADELPHIA FED)\b"),
 ("FOMC decision / Powell presser", r"\b(FOMC|FED (CUTS|HOLDS|RAISES|LEAVES|KEEPS)|RATE DECISION|DOT PLOT|POWELL:|POWELL SAYS|FED CHAIR JEROME POWELL|FED STATEMENT|FOMC MINUTES|FED MINUTES)\b"),
 ("Fed chair / Fed independence politics", r"\b(WARSH|HASSETT|FED CHAIR (RACE|PICK|NOMINEE|NOMINATION)|FIRE POWELL|FIRING POWELL|REMOVE POWELL|LISA COOK|FED INDEPENDENCE|NEXT FED CHAIR)\b"),
 ("Fed speakers", r"\b(FED'S|FED’S|WALLER|MIRAN|BOWMAN|JEFFERSON|WILLIAMS|GOOLSBEE|DALY|BOSTIC|KASHKARI|LOGAN|HAMMACK|MUSALEM|SCHMID|BARKIN|MUSALEM|BARR|PAULSON|COLLINS|HARKER)\b"),
 ("Iran / Middle East war", r"\b(IRAN|IRANIAN|TEHRAN|ISRAEL|ISRAELI|IDF|HEZBOLLAH|HAMAS|HOUTHI|HOUTHIS|GAZA|STRAIT OF HORMUZ|HORMUZ|KHAMENEI|NETANYAHU|IRGC|LEBANON|YEMEN|SYRIA|QATAR|SAUDI)\b"),
 ("Russia / Ukraine", r"\b(RUSSIA|RUSSIAN|UKRAINE|UKRAINIAN|PUTIN|ZELENSKY|ZELENSKIY|KREMLIN|MOSCOW|KYIV)\b"),
 ("Venezuela / LatAm / other geo", r"\b(VENEZUELA|MADURO|GREENLAND|PANAMA|CUBA|NORTH KOREA|PYONGYANG|TAIWAN|MISSILE|AIRSTRIKE|AIRSTRIKES|INVASION|MILITARY STRIKE|NUCLEAR|WARHEADS?|NATO|MACRON)\b"),
 ("Tariffs / trade war", r"\b(TARIFF|TARIFFS|TRADE DEAL|TRADE WAR|SECTION 232|SECTION 301|IEEPA|DE MINIMIS|EXPORT CONTROLS?|RARE EARTHS?)\b"),
 ("US-China", r"\b(CHINA|CHINESE|BEIJING|XI JINPING|XI:)\b"),
 ("Gold/CB fundamentals (PBOC, ETF, CB buying)", r"\b(GOLD|BULLION|PBOC|GOLD RESERVES|CENTRAL BANK BUYING|GOLD ETF|SPDR|COMEX|PRECIOUS METALS?|SILVER|PLATINUM)\b"),
 ("US fiscal / Treasury / shutdown / debt", r"\b(TREASURY YIELDS?|10-YEAR|10Y|30-YEAR|2-YEAR|BOND AUCTION|AUCTION|BESSENT|SHUTDOWN|DEBT CEILING|DEFICIT|MOODY'S|DOWNGRADE|SUPREME COURT|STABLECOIN)\b"),
 ("Dollar / FX", r"\b(DOLLAR|DXY|USD|YEN|USDJPY|EUR/USD|EURUSD|YUAN|INTERVENTION)\b"),
 ("Other central banks (ECB/BOJ/BOE/SNB)", r"\b(ECB|LAGARDE|BOJ|BANK OF JAPAN|UEDA|BOE|BANK OF ENGLAND|BAILEY|SNB|RBA|BOC|BANK OF CANADA|PBOC RATE|LPR)\b"),
 ("Trump (other statements)", r"\b(TRUMP|WHITE HOUSE|LEAVITT)\b"),
 ("Oil / energy", r"\b(OIL|CRUDE|BRENT|WTI|OPEC|OPEC\+|NATURAL GAS|LNG)\b"),
 ("Crypto", r"\b(BITCOIN|BTC|ETHEREUM|ETH|CRYPTO|SOLANA|XRP|BINANCE|COINBASE|MICROSTRATEGY|SAYLOR)\b"),
 ("Equities / earnings / corporate", r"(\$[A-Z]{1,5}\b|\bEARNINGS\b|\bEPS\b|\bREVENUE\b|\bSHARES\b|\bS&P\b|\bNASDAQ\b|\bDOW\b|\bIPO\b|\bNVIDIA\b|\bAPPLE\b|\bTESLA\b|\bOPENAI\b|\bAI\b)"),
]
COMP = [(n, re.compile(p)) for n, p in CATS]
SCHEDULED = {"US CPI/PPI inflation","US jobs (NFP/claims/JOLTS/ADP)","US growth data (GDP/ISM/retail/PMI)","FOMC decision / Powell presser"}
def classify(text):
    t = text.upper()
    if re.match(r"^\s*\$[A-Z]{1,6}\b", t) and not re.search(r"\$(GLD|GDX|NEM|IAU|SLV)\b", t): return "Equities / earnings / corporate"
    for n, rx in COMP:
        if rx.search(t): return n
    return "Other / misc"
